import { createSignal, createMemo, type Accessor } from "solid-js";

export interface CreatePaginationOptions {
  /** Total number of items across all pages, or total count. */
  count?: number | Accessor<number>;
  /** Explicit total number of pages. If provided, overrides count / pageSize calculation. */
  totalPages?: number | Accessor<number>;
  /** Controlled active page number (1-indexed). */
  page?: number | Accessor<number>;
  /** Default active page number for uncontrolled state. Defaults to 1. */
  defaultPage?: number;
  /** Number of items per page. Defaults to 10. */
  pageSize?: number | Accessor<number>;
  /** Number of sibling page buttons visible on each side of the current active page. Defaults to 1. */
  siblingCount?: number | Accessor<number>;
  /** Number of boundary pages visible at the beginning and end. Defaults to 1. */
  boundaries?: number | Accessor<number>;
  /** Callback fired whenever the active page changes. */
  onChange?: (page: number) => void;
}

export interface CreatePaginationReturn {
  /** Accessor returning the current active page number (1-indexed). */
  page: Accessor<number>;
  /** Accessor returning the calculated total number of pages. */
  totalPages: Accessor<number>;
  /** Accessor returning the active page size. */
  pageSize: Accessor<number>;
  /** Accessor returning an array of page numbers and "ellipsis" strings. */
  range: Accessor<(number | "ellipsis")[]>;
  /** Function to programmatically change to a specific page number. */
  setPage: (page: number) => void;
  /** Function to navigate to the next page. */
  next: () => void;
  /** Function to navigate to the previous page. */
  previous: () => void;
  /** Function to navigate to the first page (1). */
  first: () => void;
  /** Function to navigate to the last page (totalPages). */
  last: () => void;
  /** Accessor indicating whether a next page exists. */
  hasNext: Accessor<boolean>;
  /** Accessor indicating whether a previous page exists. */
  hasPrevious: Accessor<boolean>;
  /** 1-based start index of items on the current page (e.g. 1 for page 1 with pageSize 10). */
  startIndex: Accessor<number>;
  /** 1-based end index of items on the current page (e.g. 10 for page 1 with pageSize 10). */
  endIndex: Accessor<number>;
}

/**
 * SolidJS reactive primitive for computing pagination state, dynamic page range with ellipses, and navigation helpers.
 *
 * @param options Pagination configuration options.
 */
export function createPagination(options: CreatePaginationOptions = {}): CreatePaginationReturn {
  const getCount = () => {
    const raw = typeof options.count === "function" ? options.count() : options.count ?? 0;
    return Math.max(0, raw);
  };

  const getPageSize = () => {
    const raw = typeof options.pageSize === "function" ? options.pageSize() : options.pageSize ?? 10;
    return Math.max(1, raw);
  };

  const getExplicitTotalPages = () => {
    const raw = typeof options.totalPages === "function" ? options.totalPages() : options.totalPages;
    return raw !== undefined ? Math.max(1, raw) : undefined;
  };

  const getSiblingCount = () => {
    const raw = typeof options.siblingCount === "function" ? options.siblingCount() : options.siblingCount ?? 1;
    return Math.max(0, raw);
  };

  const getBoundaries = () => {
    const raw = typeof options.boundaries === "function" ? options.boundaries() : options.boundaries ?? 1;
    return Math.max(0, raw);
  };

  const [internalPage, setInternalPage] = createSignal<number>(Math.max(1, options.defaultPage ?? 1));

  const totalPages = createMemo<number>(() => {
    const explicit = getExplicitTotalPages();
    if (explicit !== undefined) {
      return Math.max(1, explicit);
    }
    const count = getCount();
    const size = getPageSize();
    return Math.max(1, Math.ceil(count / size));
  });

  const rawPage = () => {
    if (typeof options.page === "function") {
      return options.page();
    }
    if (typeof options.page === "number") {
      return options.page;
    }
    return internalPage();
  };

  const page = createMemo<number>(() => {
    const p = rawPage();
    const max = totalPages();
    if (p < 1) return 1;
    if (p > max) return max;
    return p;
  });

  const setPage = (nextPage: number) => {
    const max = totalPages();
    const clamped = Math.max(1, Math.min(nextPage, max));
    if (typeof options.page !== "function" && typeof options.page !== "number") {
      setInternalPage(clamped);
    }
    options.onChange?.(clamped);
  };

  const next = () => setPage(page() + 1);
  const previous = () => setPage(page() - 1);
  const first = () => setPage(1);
  const last = () => setPage(totalPages());

  const hasNext = createMemo(() => page() < totalPages());
  const hasPrevious = createMemo(() => page() > 1);

  const startIndex = createMemo(() => {
    const count = getCount();
    if (count === 0 && getExplicitTotalPages() === undefined) return 0;
    return (page() - 1) * getPageSize() + 1;
  });

  const endIndex = createMemo(() => {
    const count = getCount();
    const calculated = page() * getPageSize();
    if (count > 0) {
      return Math.min(calculated, count);
    }
    return calculated;
  });

  const range = createMemo<(number | "ellipsis")[]>(() => {
    const total = totalPages();
    const current = page();
    const siblings = getSiblingCount();
    const boundaries = getBoundaries();

    if (total <= 1) {
      return [1];
    }

    const pagesSet = new Set<number>();

    // 1. Boundary pages at the start
    for (let i = 1; i <= Math.min(boundaries, total); i++) {
      pagesSet.add(i);
    }

    // 2. Sibling pages around current page
    const leftSibling = Math.max(1, current - siblings);
    const rightSibling = Math.min(total, current + siblings);
    for (let i = leftSibling; i <= rightSibling; i++) {
      pagesSet.add(i);
    }

    // 3. Boundary pages at the end
    for (let i = Math.max(1, total - boundaries + 1); i <= total; i++) {
      pagesSet.add(i);
    }

    const sortedPages = Array.from(pagesSet).sort((a, b) => a - b);
    const result: (number | "ellipsis")[] = [];

    for (let i = 0; i < sortedPages.length; i++) {
      const currentPageNum = sortedPages[i];
      if (i > 0) {
        const prevPageNum = sortedPages[i - 1];
        const gap = currentPageNum - prevPageNum;
        if (gap === 2) {
          result.push(prevPageNum + 1);
        } else if (gap > 2) {
          result.push("ellipsis");
        }
      }
      result.push(currentPageNum);
    }

    return result;
  });

  return {
    page,
    totalPages,
    pageSize: getPageSize,
    range,
    setPage,
    next,
    previous,
    first,
    last,
    hasNext,
    hasPrevious,
    startIndex,
    endIndex,
  };
}

apps/web/src/hooks/create-permission.ts.content:
import { createSignal, createEffect, onCleanup, type Accessor } from "solid-js";

export type PermissionNameType =
  | "geolocation"
  | "notifications"
  | "persistent-storage"
  | "push"
  | "screen-wake-lock"
  | "clipboard-read"
  | "clipboard-write"
  | "camera"
  | "microphone"
  | (string & {});

export type PermissionStatusState = "granted" | "denied" | "prompt" | "unknown";

export interface CreatePermissionOptions {
  /** Permission descriptor or name to query. */
  name: PermissionNameType;
}

export interface CreatePermissionReturn {
  /** Signal accessor containing current permission status ('granted', 'denied', 'prompt', 'unknown'). */
  state: Accessor<PermissionStatusState>;
  /** Signal accessor indicating whether Permissions API is supported in browser environment. */
  isSupported: Accessor<boolean>;
  /** Imperative function to re-query permission status manually. */
  query: () => Promise<PermissionStatusState>;
}

/**
 * SolidJS reactive primitive for querying and observing browser permission status changes.
 */
export function createPermission(
  options: PermissionNameType | CreatePermissionOptions
): CreatePermissionReturn {
  const [state, setState] = createSignal<PermissionStatusState>("unknown");

  const permissionName = typeof options === "string" ? options : options.name;

  const isSupported = (): boolean =>
    typeof window !== "undefined" &&
    typeof navigator !== "undefined" &&
    "permissions" in navigator;

  let permissionStatus: PermissionStatus | null = null;

  const query = async (): Promise<PermissionStatusState> => {
    if (!isSupported()) {
      setState("unknown");
      return "unknown";
    }

    try {
      const status = await navigator.permissions.query({
        name: permissionName as PermissionName,
      });

      permissionStatus = status;
      const currentState = status.state as PermissionStatusState;
      setState(currentState);

      status.onchange = () => {
        setState(status.state as PermissionStatusState);
      };

      return currentState;
    } catch {
      setState("unknown");
      return "unknown";
    }
  };

  createEffect(() => {
    if (!isSupported()) return;

    query();

    onCleanup(() => {
      if (permissionStatus) {
        permissionStatus.onchange = null;
      }
    });
  });

  return {
    state,
    isSupported,
    query,
  };
}

apps/web/src/hooks/create-previous.ts.content:
import { createEffect, createSignal, type Accessor } from "solid-js";

/**
 * SolidJS reactive primitive for tracking previous value of a signal accessor.
 *
 * @param source Target reactive signal accessor to observe.
 */
export function createPrevious<T>(source: Accessor<T>): Accessor<T | undefined> {
  const [previous, setPrevious] = createSignal<T | undefined>(undefined);
  let current: T = source();

  createEffect(() => {
    const next = source();
    if (current !== next) {
      setPrevious(() => current);
      current = next;
    }
  });

  return previous;
}

apps/web/src/hooks/create-resize-observe.content:
import { createEffect, createSignal, onCleanup, type Accessor } from "solid-js";

export interface CreateResizeObserverOptions extends ResizeObserverOptions {
  /** Whether the observer is active. Defaults to true. */
  enabled?: boolean | Accessor<boolean>;
}

/**
 * SolidJS reactive primitive for observing element size changes via ResizeObserver.
 *
 * @param target Target element or accessor returning HTML element.
 * @param callback Observer callback invoked on element resize events.
 * @param options ResizeObserver options (box, enabled).
 */
export function createResizeObserver(
  target: HTMLElement | Accessor<HTMLElement | undefined>,
  callback: ResizeObserverCallback,
  options: CreateResizeObserverOptions = {}
): void {
  const getTarget = (): HTMLElement | undefined => {
    if (typeof target === "function") {
      return (target as Accessor<HTMLElement | undefined>)();
    }
    return target;
  };

  const isEnabled = (): boolean => {
    if (typeof options.enabled === "function") {
      return options.enabled();
    }
    return options.enabled ?? true;
  };

  createEffect(() => {
    if (typeof window === "undefined" || !window.ResizeObserver) {
      return;
    }

    if (!isEnabled()) return;

    const el = getTarget();
    if (!el) return;

    const observer = new ResizeObserver(callback);
    observer.observe(el, { box: options.box });

    onCleanup(() => {
      observer.disconnect();
    });
  });
}

export interface CreateElementSizeReturn {
  /** Accessor for element width in pixels */
  width: Accessor<number>;
  /** Accessor for element height in pixels */
  height: Accessor<number>;
}

/**
 * SolidJS reactive primitive returning width and height accessors for a target HTML element.
 *
 * @param target Target element or accessor returning HTML element.
 * @param options ResizeObserver options.
 */
export function createElementSize(
  target: HTMLElement | Accessor<HTMLElement | undefined>,
  options: CreateResizeObserverOptions = {}
): CreateElementSizeReturn {
  const [width, setWidth] = createSignal(0);
  const [height, setHeight] = createSignal(0);

  createResizeObserver(
    target,
    (entries) => {
      const entry = entries[0];
      if (entry) {
        setWidth(entry.contentRect.width);
        setHeight(entry.contentRect.height);
      }
    },
    options
  );

  return {
    width,
    height,
  };
}

apps/web/src/hooks/create-scroll-into-vi.content:
import { createEffect, onCleanup, type Accessor } from "solid-js";

export interface CreateScrollIntoViewOptions extends ScrollIntoViewOptions {
  /** Whether the element should scroll into view automatically. Defaults to true. */
  enabled?: boolean | Accessor<boolean>;
  /** Delay in milliseconds before executing scrollIntoView. Defaults to 0. */
  delay?: number;
}

/**
 * SolidJS reactive primitive for scrolling a target element into view smooth or auto behavior.
 */
export function createScrollIntoView(
  target: HTMLElement | Accessor<HTMLElement | null | undefined> | null | undefined,
  options: CreateScrollIntoViewOptions = {}
): void {
  const getTarget = (): HTMLElement | null | undefined => {
    if (typeof target === "function") {
      return target();
    }
    return target;
  };

  const isEnabled = (): boolean => {
    if (typeof options.enabled === "function") {
      return options.enabled();
    }
    return options.enabled ?? true;
  };

  createEffect(() => {
    if (!isEnabled()) return;

    const el = getTarget();
    if (!el || typeof window === "undefined") return;

    const scrollOptions: ScrollIntoViewOptions = {
      behavior: options.behavior ?? "smooth",
      block: options.block ?? "nearest",
      inline: options.inline ?? "nearest",
    };

    let timer: ReturnType<typeof setTimeout> | null = null;

    if (options.delay && options.delay > 0) {
      timer = setTimeout(() => {
        el.scrollIntoView(scrollOptions);
      }, options.delay);
    } else {
      el.scrollIntoView(scrollOptions);
    }

    onCleanup(() => {
      if (timer) clearTimeout(timer);
    });
  });
}

apps/web/src/hooks/create-scroll-positio.content:
import { createEffect, createSignal, onCleanup, type Accessor } from "solid-js";

export type ScrollDirection = "up" | "down" | "left" | "right" | "none";

export interface CreateScrollPositionOptions {
  /** Target element to observe scroll events on. Defaults to window. */
  target?: HTMLElement | Window | Accessor<HTMLElement | Window | undefined>;
}

export interface CreateScrollPositionReturn {
  /** Accessor for horizontal scroll position (scrollLeft / pageXOffset) */
  x: Accessor<number>;
  /** Accessor for vertical scroll position (scrollTop / pageYOffset) */
  y: Accessor<number>;
  /** Accessor indicating if element is actively scrolling */
  isScrolling: Accessor<boolean>;
  /** Accessor for current scroll direction ('up', 'down', 'left', 'right', 'none') */
  direction: Accessor<ScrollDirection>;
  /** Accessor indicating if scroll is at top (y <= 0) */
  isAtTop: Accessor<boolean>;
  /** Accessor indicating if scroll is at bottom of container */
  isAtBottom: Accessor<boolean>;
  /** Function to programmatically scroll target element */
  scrollTo: (options: ScrollToOptions) => void;
}

/**
 * SolidJS reactive primitive for tracking target element or window scroll position and scroll metrics.
 *
 * @param options Configuration options including target element.
 */
export function createScrollPosition(
  options: CreateScrollPositionOptions = {}
): CreateScrollPositionReturn {
  const [x, setX] = createSignal(0);
  const [y, setY] = createSignal(0);
  const [isScrolling, setIsScrolling] = createSignal(false);
  const [direction, setDirection] = createSignal<ScrollDirection>("none");
  const [isAtTop, setIsAtTop] = createSignal(true);
  const [isAtBottom, setIsAtBottom] = createSignal(false);

  let scrollTimeout: ReturnType<typeof setTimeout> | undefined;
  let lastX = 0;
  let lastY = 0;

  const getTarget = (): HTMLElement | Window | undefined => {
    if (typeof window === "undefined") return undefined;
    if (!options.target) return window;
    if (typeof options.target === "function") {
      return (options.target as Accessor<HTMLElement | Window | undefined>)();
    }
    return options.target;
  };

  const updateScroll = () => {
    const target = getTarget();
    if (!target) return;

    let currentX = 0;
    let currentY = 0;
    let maxScrollY = 0;

    if (target === window) {
      currentX = window.scrollX || window.pageXOffset;
      currentY = window.scrollY || window.pageYOffset;
      maxScrollY = document.documentElement.scrollHeight - window.innerHeight;
    } else {
      const el = target as HTMLElement;
      currentX = el.scrollLeft;
      currentY = el.scrollTop;
      maxScrollY = el.scrollHeight - el.clientHeight;
    }

    // Determine direction
    const deltaX = currentX - lastX;
    const deltaY = currentY - lastY;

    if (Math.abs(deltaY) > Math.abs(deltaX)) {
      if (deltaY > 0) setDirection("down");
      else if (deltaY < 0) setDirection("up");
    } else if (Math.abs(deltaX) > 0) {
      if (deltaX > 0) setDirection("right");
      else if (deltaX < 0) setDirection("left");
    }

    lastX = currentX;
    lastY = currentY;

    setX(currentX);
    setY(currentY);
    setIsAtTop(currentY <= 0);
    setIsAtBottom(maxScrollY > 0 && currentY >= maxScrollY - 1);
    setIsScrolling(true);

    if (scrollTimeout) clearTimeout(scrollTimeout);
    scrollTimeout = setTimeout(() => {
      setIsScrolling(false);
    }, 150);
  };

  createEffect(() => {
    const target = getTarget();
    if (!target) return;

    updateScroll();

    target.addEventListener("scroll", updateScroll, { passive: true });
    onCleanup(() => {
      target.removeEventListener("scroll", updateScroll);
      if (scrollTimeout) clearTimeout(scrollTimeout);
    });
  });

  const scrollTo = (scrollOptions: ScrollToOptions) => {
    const target = getTarget();
    if (!target) return;
    target.scrollTo(scrollOptions);
  };

  return {
    x,
    y,
    isScrolling,
    direction,
    isAtTop,
    isAtBottom,
    scrollTo,
  };
}

apps/web/src/hooks/create-storage.ts.content:
import { createSignal, onMount, onCleanup, type Accessor } from "solid-js";

export type StorageType = "local" | "session";

/**
 * Helper to safely read item from Web Storage.
 */
function readStorage<T>(key: string, storage: Storage | undefined, fallback: T): T {
  if (!storage) return fallback;
  try {
    const item = storage.getItem(key);
    return item !== null ? JSON.parse(item) : fallback;
  } catch (error) {
    console.warn(`[nikala-ui/hooks] Error reading storage key "${key}":`, error);
    return fallback;
  }
}

/**
 * SolidJS reactive primitive for Web Storage (localStorage / sessionStorage) synchronization.
 *
 * @param key Storage key name.
 * @param initialValue Default initial value if key doesn't exist.
 * @param type Storage type: "local" (default) or "session".
 */
export function createStorage<T>(
  key: string,
  initialValue: T | Accessor<T>,
  type: StorageType = "local"
): [value: Accessor<T>, setValue: (val: T | ((prev: T) => T)) => void, remove: () => void] {
  const getStorage = (): Storage | undefined => {
    if (typeof window === "undefined") return undefined;
    return type === "local" ? window.localStorage : window.sessionStorage;
  };

  const getFallback = (): T => (typeof initialValue === "function" ? (initialValue as Accessor<T>)() : initialValue);

  const [value, setInternalValue] = createSignal<T>(getFallback());

  const setValue = (val: T | ((prev: T) => T)) => {
    const storage = getStorage();
    const currentValue = value();
    const nextValue = typeof val === "function" ? (val as (prev: T) => T)(currentValue) : val;

    setInternalValue(() => nextValue);

    if (storage) {
      try {
        storage.setItem(key, JSON.stringify(nextValue));
      } catch (error) {
        console.warn(`[nikala-ui/hooks] Error setting storage key "${key}":`, error);
      }
    }
  };

  const remove = () => {
    const storage = getStorage();
    setInternalValue(() => getFallback());
    if (storage) {
      storage.removeItem(key);
    }
  };

  onMount(() => {
    if (typeof window === "undefined") return;

    const storage = getStorage();
    if (storage) {
      const stored = readStorage<T>(key, storage, getFallback());
      setInternalValue(() => stored);
    }

    const handleStorageChange = (event: StorageEvent) => {
      if (event.key === key) {
        setInternalValue(() => (event.newValue !== null ? JSON.parse(event.newValue) : getFallback()));
      }
    };

    window.addEventListener("storage", handleStorageChange);
    onCleanup(() => {
      window.removeEventListener("storage", handleStorageChange);
    });
  });

  return [value, setValue, remove];
}

/**
 * SolidJS reactive primitive for localStorage synchronization across components and browser tabs.
 */
export function createLocalStorage<T>(
  key: string,
  initialValue: T | Accessor<T>
): [value: Accessor<T>, setValue: (val: T | ((prev: T) => T)) => void, remove: () => void] {
  return createStorage<T>(key, initialValue, "local");
}

/**
 * SolidJS reactive primitive for sessionStorage synchronization.
 */
export function createSessionStorage<T>(
  key: string,
  initialValue: T | Accessor<T>
): [value: Accessor<T>, setValue: (val: T | ((prev: T) => T)) => void, remove: () => void] {
  return createStorage<T>(key, initialValue, "session");
}

apps/web/src/hooks/create-tauri-window.t.content:
import { createSignal, onMount, onCleanup, type Accessor } from "solid-js";

export type TauriPlatform = "macos" | "windows" | "linux" | "web";

export interface CreateTauriWindowOptions {
  /** Initial fallback platform if not detected automatically. */
  defaultPlatform?: TauriPlatform;
  /** Listen to window resize and focus events. Defaults to true. */
  listenEvents?: boolean;
}

export interface CreateTauriWindowReturn {
  /** Signal indicating whether the application is running inside a Tauri runtime. */
  isTauri: Accessor<boolean>;
  /** Detected host platform ('macos' | 'windows' | 'linux' | 'web'). */
  platform: Accessor<TauriPlatform>;
  /** Signal indicating whether the window is currently maximized. */
  isMaximized: Accessor<boolean>;
  /** Signal indicating whether the window is currently minimized. */
  isMinimized: Accessor<boolean>;
  /** Signal indicating whether the window is currently in fullscreen mode. */
  isFullscreen: Accessor<boolean>;
  /** Signal indicating whether the window is currently focused. */
  isFocused: Accessor<boolean>;
  /** Minimize the application window. */
  minimize: () => Promise<void>;
  /** Maximize the application window. */
  maximize: () => Promise<void>;
  /** Unmaximize the application window. */
  unmaximize: () => Promise<void>;
  /** Toggle between maximized and normal window states. */
  toggleMaximize: () => Promise<void>;
  /** Close the application window or exit process if main window. */
  close: () => Promise<void>;
  /** Forcefully destroy/close the application window. */
  destroy: () => Promise<void>;
  /** Toggle fullscreen state. */
  setFullscreen: (fullscreen: boolean) => Promise<void>;
  /** Start dragging the window. Can be bound to mousedown event or custom titlebar headers. */
  startDragging: (e?: MouseEvent) => Promise<void>;
}

/**
 * Helper to detect current operating system in browser or desktop environments.
 */
export function detectPlatform(): TauriPlatform {
  if (typeof window === "undefined" || typeof navigator === "undefined") {
    return "web";
  }

  const userAgent = navigator.userAgent.toLowerCase();
  const platform =
    (navigator as any).userAgentData?.platform?.toLowerCase() ||
    navigator.platform?.toLowerCase() ||
    "";

  if (platform.includes("mac") || userAgent.includes("macintosh") || userAgent.includes("mac os x")) {
    return "macos";
  }
  if (platform.includes("win") || userAgent.includes("windows")) {
    return "windows";
  }
  if (platform.includes("linux") || userAgent.includes("linux")) {
    return "linux";
  }

  return "web";
}

/**
 * Checks whether the current environment is running inside Tauri v1 or v2.
 */
export function isTauriEnvironment(): boolean {
  if (typeof window === "undefined") return false;
  const win = window as any;
  return Boolean(
    win.__TAURI_INTERNALS__ ||
    win.__TAURI__ ||
    win.__TAURI_PATTERN__ ||
    win.__TAURI_METADATA__ ||
    win.__TAURI_IPC__ ||
    win.__TAURI_WINDOW__
  );
}

/**
 * Checks whether the current environment is running inside Electron.
 */
export function isElectronEnvironment(): boolean {
  if (typeof window === "undefined") return false;
  const win = window as any;
  return Boolean(
    win.electron ||
    win.electronAPI ||
    win.ipcRenderer ||
    win.process?.versions?.electron ||
    (typeof navigator !== "undefined" && navigator.userAgent?.toLowerCase().includes("electron"))
  );
}

/**
 * Direct low-level IPC invocation across Tauri v2 (__TAURI_INTERNALS__) and Tauri v1.
 */
async function invokeTauri(
  v2Cmd: string,
  v2Args?: Record<string, any>,
  v1CmdType?: string,
  v1Data?: any
): Promise<any> {
  if (typeof window === "undefined") return undefined;
  const win = window as any;

  // 1. Try Tauri v2 direct IPC via injected __TAURI_INTERNALS__ or core.invoke
  const invokeV2 = win.__TAURI_INTERNALS__?.invoke || win.__TAURI__?.core?.invoke;
  if (typeof invokeV2 === "function") {
    try {
      return await invokeV2(`plugin:window|${v2Cmd}`, v2Args || {});
    } catch {
      // Fallback to secondary invoke mechanisms
    }
  }

  // 2. Try Tauri v1 / generic invoke
  const invokeV1 = win.__TAURI__?.invoke || win.__TAURI_INVOKE__;
  if (typeof invokeV1 === "function") {
    try {
      if (v1CmdType) {
        return await invokeV1("tauri", {
          __tauriModule: "Window",
          message: {
            cmd: "manage",
            data: {
              cmd: {
                type: v1CmdType,
                ...(v1Data !== undefined ? { data: v1Data } : {}),
              },
            },
          },
        });
      }
      return await invokeV1(v2Cmd, v2Args);
    } catch {
      // Fallback
    }
  }

  return undefined;
}

/**
 * Helper to send Electron IPC messages if running in an Electron shell.
 */
function sendElectronMessage(channel: string, ...args: any[]): boolean {
  if (typeof window === "undefined") return false;
  const win = window as any;

  try {
    if (win.electronAPI && typeof win.electronAPI[channel] === "function") {
      win.electronAPI[channel](...args);
      return true;
    }
    if (win.electron?.ipcRenderer?.send) {
      win.electron.ipcRenderer.send(channel, ...args);
      return true;
    }
    if (win.ipcRenderer?.send) {
      win.ipcRenderer.send(channel, ...args);
      return true;
    }
    if (typeof win.require === "function") {
      const electron = win.require("electron");
      if (electron?.ipcRenderer?.send) {
        electron.ipcRenderer.send(channel, ...args);
        return true;
      }
    }
  } catch {
    // Ignored
  }
  return false;
}

/**
 * SolidJS reactive primitive for controlling and observing desktop window states.
 * Supports Tauri v2, Tauri v1, Electron, and browser preview environments.
 */
export function createTauriWindow(
  options: CreateTauriWindowOptions = {}
): CreateTauriWindowReturn {
  const [isTauri, setIsTauri] = createSignal<boolean>(false);
  const [platform, setPlatform] = createSignal<TauriPlatform>(options.defaultPlatform || "web");
  const [isMaximized, setIsMaximized] = createSignal<boolean>(false);
  const [isMinimized, setIsMinimized] = createSignal<boolean>(false);
  const [isFullscreen, setIsFullscreen] = createSignal<boolean>(false);
  const [isFocused, setIsFocused] = createSignal<boolean>(true);

  let unlistenResize: (() => void) | null = null;
  let unlistenFocus: (() => void) | null = null;

  // Retrieve Tauri Window instance safely
  const getTauriWindow = async () => {
    if (typeof window === "undefined") return null;
    const win = window as any;
    try {
      if (win.__TAURI__?.window?.getCurrentWindow) {
        return win.__TAURI__.window.getCurrentWindow();
      }
      if (win.__TAURI__?.window?.appWindow) {
        return win.__TAURI__.window.appWindow;
      }
      if (win.__TAURI_WINDOW__?.getCurrentWindow) {
        return win.__TAURI_WINDOW__.getCurrentWindow();
      }
      if (win.__TAURI_WINDOW__?.appWindow) {
        return win.__TAURI_WINDOW__.appWindow;
      }
      // Dynamic import if bundled by user's build setup
      const moduleName = "@tauri-apps/api/window";
      // @ts-ignore - Optional runtime dependency in Tauri apps
      const tauriApi = await import(/* @vite-ignore */ moduleName).catch(() => null);
      if (tauriApi?.getCurrentWindow) {
        return tauriApi.getCurrentWindow();
      }
      if (tauriApi?.appWindow) {
        return tauriApi.appWindow;
      }
    } catch {
      // Running in standard web mode
    }
    return null;
  };

  const updateWindowStates = async () => {
    if (typeof window === "undefined") return;

    const tauriWin = await getTauriWindow();
    if (tauriWin) {
      setIsTauri(true);
      try {
        const [max, min, full, foc] = await Promise.all([
          typeof tauriWin.isMaximized === "function" ? tauriWin.isMaximized() : false,
          typeof tauriWin.isMinimized === "function" ? tauriWin.isMinimized() : false,
          typeof tauriWin.isFullscreen === "function" ? tauriWin.isFullscreen() : false,
          typeof tauriWin.isFocused === "function" ? tauriWin.isFocused() : true,
        ]);
        setIsMaximized(Boolean(max));
        setIsMinimized(Boolean(min));
        setIsFullscreen(Boolean(full));
        setIsFocused(Boolean(foc));
        return;
      } catch {
        // Fallback gracefully
      }
    }

    if (isTauriEnvironment()) {
      setIsTauri(true);
      try {
        const max = await invokeTauri("is_maximized", {}, "isMaximized");
        if (typeof max === "boolean") setIsMaximized(max);
        const min = await invokeTauri("is_minimized", {}, "isMinimized");
        if (typeof min === "boolean") setIsMinimized(min);
        const full = await invokeTauri("is_fullscreen", {}, "isFullscreen");
        if (typeof full === "boolean") setIsFullscreen(full);
        const foc = await invokeTauri("is_focused", {}, "isFocused");
        if (typeof foc === "boolean") setIsFocused(foc);
        return;
      } catch {
        // Fallback
      }
    }

    if (!isElectronEnvironment()) {
      setIsTauri(false);
    }
    if (typeof document !== "undefined") {
      setIsFullscreen(Boolean(document.fullscreenElement));
    }
  };

  onMount(async () => {
    if (typeof window === "undefined") return;

    setPlatform(detectPlatform());
    setIsTauri(isTauriEnvironment());
    await updateWindowStates();

    if (options.listenEvents !== false) {
      const handleWindowFocus = () => setIsFocused(true);
      const handleWindowBlur = () => setIsFocused(false);
      const handleFullscreenChange = () => setIsFullscreen(Boolean(document.fullscreenElement));
      const handleResize = () => {
        updateWindowStates();
      };

      window.addEventListener("focus", handleWindowFocus);
      window.addEventListener("blur", handleWindowBlur);
      window.addEventListener("resize", handleResize);
      document.addEventListener("fullscreenchange", handleFullscreenChange);

      const tauriWin = await getTauriWindow();
      if (tauriWin?.onResized) {
        try {
          unlistenResize = await tauriWin.onResized(() => updateWindowStates());
          unlistenFocus = await tauriWin.onFocusChanged(({ payload }: { payload: boolean }) => {
            setIsFocused(payload);
          });
        } catch {
          // Ignored in non-tauri contexts
        }
      }

      onCleanup(() => {
        window.removeEventListener("focus", handleWindowFocus);
        window.removeEventListener("blur", handleWindowBlur);
        window.removeEventListener("resize", handleResize);
        document.removeEventListener("fullscreenchange", handleFullscreenChange);
        if (unlistenResize) unlistenResize();
        if (unlistenFocus) unlistenFocus();
      });
    }
  });

  const minimize = async (): Promise<void> => {
    let executed = false;
    const tauriWin = await getTauriWindow();
    if (tauriWin?.minimize) {
      try {
        await tauriWin.minimize();
        executed = true;
      } catch {}
    }
    if (!executed && isTauriEnvironment()) {
      try {
        await invokeTauri("minimize", {}, "minimize");
        executed = true;
      } catch {}
    }
    if (!executed && isElectronEnvironment()) {
      executed =
        sendElectronMessage("window-minimize") ||
        sendElectronMessage("minimize") ||
        sendElectronMessage("windowMinimize");
    }

    setIsMinimized(true);
    setIsMaximized(false);
  };

  const maximize = async (): Promise<void> => {
    let executed = false;
    const tauriWin = await getTauriWindow();
    if (tauriWin?.maximize) {
      try {
        await tauriWin.maximize();
        executed = true;
      } catch {}
    }
    if (!executed && isTauriEnvironment()) {
      try {
        await invokeTauri("maximize", {}, "maximize");
        executed = true;
      } catch {}
    }
    if (!executed && isElectronEnvironment()) {
      executed =
        sendElectronMessage("window-maximize") ||
        sendElectronMessage("maximize") ||
        sendElectronMessage("windowMaximize");
    }

    setIsMaximized(true);
    setIsMinimized(false);
  };

  const unmaximize = async (): Promise<void> => {
    let executed = false;
    const tauriWin = await getTauriWindow();
    if (tauriWin?.unmaximize) {
      try {
        await tauriWin.unmaximize();
        executed = true;
      } catch {}
    }
    if (!executed && isTauriEnvironment()) {
      try {
        await invokeTauri("unmaximize", {}, "unmaximize");
        executed = true;
      } catch {}
    }
    if (!executed && isElectronEnvironment()) {
      executed =
        sendElectronMessage("window-unmaximize") ||
        sendElectronMessage("unmaximize") ||
        sendElectronMessage("windowRestore") ||
        sendElectronMessage("restore");
    }

    setIsMaximized(false);
  };

  let lastToggleTime = 0;
  const toggleMaximize = async (): Promise<void> => {
    const now = Date.now();
    if (now - lastToggleTime < 350) {
      return; // Ignore duplicate rapid triggers within 350ms window
    }
    lastToggleTime = now;

    let executed = false;
    const tauriWin = await getTauriWindow();
    if (tauriWin) {
      try {
        if (typeof tauriWin.isMaximized === "function") {
          const isMax = await tauriWin.isMaximized();
          if (isMax && typeof tauriWin.unmaximize === "function") {
            await tauriWin.unmaximize();
            setIsMaximized(false);
            executed = true;
          } else if (!isMax && typeof tauriWin.maximize === "function") {
            await tauriWin.maximize();
            setIsMaximized(true);
            executed = true;
          }
        }
        if (!executed && typeof tauriWin.toggleMaximize === "function") {
          await tauriWin.toggleMaximize();
          executed = true;
        }
      } catch {}
    }

    if (!executed && isTauriEnvironment()) {
      try {
        const isMax = await invokeTauri("is_maximized", {}, "isMaximized");
        if (typeof isMax === "boolean") {
          if (isMax) {
            await invokeTauri("unmaximize", {}, "unmaximize");
            setIsMaximized(false);
          } else {
            await invokeTauri("maximize", {}, "maximize");
            setIsMaximized(true);
          }
          executed = true;
        } else {
          await invokeTauri("toggle_maximize", {}, "toggleMaximize");
          executed = true;
        }
      } catch {}
    }

    if (!executed && isElectronEnvironment()) {
      executed =
        sendElectronMessage("window-toggle-maximize") ||
        sendElectronMessage("toggle-maximize") ||
        sendElectronMessage("toggleMaximize");
    }

    if (!executed) {
      setIsMaximized((prev) => !prev);
    }
    setIsMinimized(false);
  };

  const close = async (): Promise<void> => {
    let closed = false;
    const win = typeof window !== "undefined" ? (window as any) : null;
    const tauriWin = await getTauriWindow();

    // 1. Try Tauri Window API close
    if (tauriWin?.close) {
      try {
        await tauriWin.close();
        closed = true;
      } catch {}
    }

    // 2. Try Tauri IPC window close
    if (!closed && isTauriEnvironment()) {
      try {
        await invokeTauri("close", {}, "close");
        closed = true;
      } catch {}
    }

    // 3. Try Tauri destroy fallback if close did not succeed
    if (!closed && tauriWin?.destroy) {
      try {
        await tauriWin.destroy();
        closed = true;
      } catch {}
    }
    if (!closed && isTauriEnvironment()) {
      try {
        await invokeTauri("destroy", {}, "destroy");
        closed = true;
      } catch {}
    }

    // 4. Try Tauri process exit if in Tauri environment
    if (!closed && isTauriEnvironment()) {
      try {
        const invokeProcess = win?.__TAURI_INTERNALS__?.invoke || win?.__TAURI__?.core?.invoke;
        if (typeof invokeProcess === "function") {
          await invokeProcess("plugin:process|exit", { code: 0 });
          closed = true;
        } else if (win?.__TAURI__?.process?.exit) {
          await win.__TAURI__.process.exit(0);
          closed = true;
        }
      } catch {}
    }

    // 5. Try Electron window close / app quit
    if (!closed && isElectronEnvironment()) {
      closed =
        sendElectronMessage("window-close") ||
        sendElectronMessage("close") ||
        sendElectronMessage("app-close") ||
        sendElectronMessage("quit");
    }

    // 6. Browser fallback & custom event dispatch
    if (typeof window !== "undefined") {
      try {
        window.dispatchEvent(new CustomEvent("nikala:window-close"));
      } catch {}

      try {
        window.close();
      } catch {}
    }
  };

  const destroy = async (): Promise<void> => {
    const tauriWin = await getTauriWindow();
    if (tauriWin?.destroy) {
      try {
        await tauriWin.destroy();
        return;
      } catch {}
    }
    if (isTauriEnvironment()) {
      try {
        await invokeTauri("destroy", {}, "destroy");
        return;
      } catch {}
    }
    await close();
  };

  const setFullscreen = async (fullscreen: boolean): Promise<void> => {
    let executed = false;
    const tauriWin = await getTauriWindow();
    if (tauriWin?.setFullscreen) {
      try {
        await tauriWin.setFullscreen(fullscreen);
        executed = true;
      } catch {}
    }
    if (!executed && isTauriEnvironment()) {
      try {
        await invokeTauri("set_fullscreen", { value: fullscreen }, "setFullscreen", fullscreen);
        executed = true;
      } catch {}
    }
    if (!executed && isElectronEnvironment()) {
      executed =
        sendElectronMessage("window-set-fullscreen", fullscreen) ||
        sendElectronMessage("set-fullscreen", fullscreen);
    }

    if (typeof document !== "undefined") {
      if (fullscreen && document.documentElement.requestFullscreen) {
        try {
          await document.documentElement.requestFullscreen();
        } catch {}
      } else if (!fullscreen && document.fullscreenElement && document.exitFullscreen) {
        try {
          await document.exitFullscreen();
        } catch {}
      }
    }

    setIsFullscreen(fullscreen);
  };

  const startDragging = async (e?: MouseEvent): Promise<void> => {
    if (e) {
      if (e.button !== 0) return; // Only primary mouse button starts drag
      if (e.detail > 1) return; // Prevent drag initialization on double-click gesture
    }
    let dragged = false;
    const tauriWin = await getTauriWindow();
    if (tauriWin?.startDragging) {
      try {
        await tauriWin.startDragging();
        dragged = true;
      } catch {}
    }
    if (!dragged && isTauriEnvironment()) {
      try {
        await invokeTauri("start_dragging", {}, "startDragging");
        dragged = true;
      } catch {}
    }
    if (!dragged && isElectronEnvironment()) {
      sendElectronMessage("window-drag");
    }
  };

  return {
    isTauri,
    platform,
    isMaximized,
    isMinimized,
    isFullscreen,
    isFocused,
    minimize,
    maximize,
    unmaximize,
    toggleMaximize,
    close,
    destroy,
    setFullscreen,
    startDragging,
  };
}

