                    disabled={!defaultPagination.hasPrevious()}
                    onClick={defaultPagination.previous}
                  />
                </PaginationItem>

                <For each={defaultPagination.range()}>
                  {(item) =>
                    item === "ellipsis" ? (
                      <PaginationItem>
                        <PaginationEllipsis />
                      </PaginationItem>
                    ) : (
                      <PaginationItem>
                        <PaginationLink
                          isActive={defaultPagination.page() === item}
                          onClick={() => defaultPagination.setPage(item)}
                        >
                          {item}
                        </PaginationLink>
                      </PaginationItem>
                    )
                  }
                </For>

                <PaginationItem>
                  <PaginationNext
                    disabled={!defaultPagination.hasNext()}
                    onClick={defaultPagination.next}
                  />
                </PaginationItem>
              </PaginationContent>
            </Pagination>
          </div>
        </ComponentPreview>

        {/* 3. Usage & Import */}
        <div class="space-y-4">
          <DocSectionHeader title="Usage" />
          <CodeBlock code={importCode} lang="tsx" />
        </div>

        {/* 4. Examples */}
        <div class="space-y-8 pt-4">
          <DocSectionHeader title="Examples" />

          {/* Outline Variant with First/Last Controls */}
          <div class="space-y-3">
