                      />
                    </PaginationItem>
                    <PaginationItem>
                      <PaginationPrevious
                        variant="outline"
                        disabled={!outlinePagination.hasPrevious()}
                        onClick={outlinePagination.previous}
                      />
                    </PaginationItem>

                    <For each={outlinePagination.range()}>
                      {(item) =>
                        item === "ellipsis" ? (
                          <PaginationItem>
                            <PaginationEllipsis />
                          </PaginationItem>
                        ) : (
                          <PaginationItem>
                            <PaginationLink
                              variant="outline"
